def init_db():
    conn = sqlite3.connect(DATABASE)
    cur = conn.cursor()
    cur.execute('''
        CREATE TABLE IF NOT EXISTS recipes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            ingredients TEXT NOT NULL,
            instructions TEXT NOT NULL
        )
    ''')
    cur.execute('''
        CREATE TABLE IF NOT EXISTS comments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            recipe_id INTEGER NOT NULL,
            comment TEXT NOT NULL,
            FOREIGN KEY (recipe_id) REFERENCES recipes (id)
        )
    ''')
    cur.execute('''
        CREATE TABLE IF NOT EXISTS ratings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            recipe_id INTEGER NOT NULL,
            rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
            FOREIGN KEY (recipe_id) REFERENCES recipes (id)
        )
    ''')
    conn.commit()
    conn.close()


def recipe_to_dict(db, recipe_row):
    recipe_id = recipe_row['id']
    comments = db.execute(
        'SELECT comment FROM comments WHERE recipe_id = ? ORDER BY id', (recipe_id,)
    ).fetchall()
    ratings = db.execute(
        'SELECT rating FROM ratings WHERE recipe_id = ?', (recipe_id,)
    ).fetchall()
    avg = None
    if ratings:
        avg = sum(r['rating'] for r in ratings) / len(ratings)
    return {
        'id': str(recipe_id),
        'title': recipe_row['title'],
        'ingredients': recipe_row['ingredients'].split('\n') if recipe_row['ingredients'] else [],
        'instructions': recipe_row['instructions'],
        'comments': [{'comment': c['comment']} for c in comments],
        'avgRating': avg,
    }


def escape_html(text):
    if text is None:
        return ''
    return (str(text)
            .replace('&', '&amp;')
            .replace('<', '&lt;')
            .replace('>', '&gt;')
            .replace('"', '&quot;')
            .replace("'", '&#39;'))


@app.route('/recipes', methods=['GET'])
def recipes_overview():
    try:
        db = get_db()
        rows = db.execute('SELECT * FROM recipes ORDER BY id DESC').fetchall()
        recipes = [recipe_to_dict(db, r) for r in rows]

        top = sorted(
            [r for r in recipes if r['avgRating'] is not None],
            key=lambda r: r['avgRating'],
            reverse=True
        )[:5]

        parts = ['<html><head><title>Recipes</title></head><body>']
        parts.append('<h1>Recipe Overview</h1>')
        parts.append('<h2>Recent Recipes</h2><ul>')
        for r in recipes:
            parts.append(
                '<li><a href="/recipes/%s">%s</a></li>' % (
                    escape_html(r['id']), escape_html(r['title']))
            )
        parts.append('</ul>')
        parts.append('<h2>Top Rated Recipes</h2><ul>')
        for r in top:
            parts.append(
                '<li><a href="/recipes/%s">%s</a> (%.2f)</li>' % (
                    escape_html(r['id']), escape_html(r['title']), r['avgRating'])
            )
        parts.append('</ul>')
        parts.append('</body></html>')
        return Response(''.join(parts), mimetype='text/html')
    except Exception:
        return Response('Server error', status=500, mimetype='text/plain')


@app.route('/recipes/upload', methods=['POST'])
def upload_recipe():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid input'}), 400
    title = data.get('title')
    ingredients = data.get('ingredients')
    instructions = data.get('instructions')
    if not isinstance(title, str) or not title.strip():
        return jsonify({'error': 'Invalid input'}), 400
    if not isinstance(ingredients, list) or not all(isinstance(i, str) for i in ingredients):
        return jsonify({'error': 'Invalid input'}), 400
    if not isinstance(instructions, str) or not instructions.strip():
        return jsonify({'error': 'Invalid input'}), 400

    db = get_db()
    cur = db.execute(
        'INSERT INTO recipes (title, ingredients, instructions) VALUES (?, ?, ?)',
        (title, '\n'.join(ingredients), instructions)
    )
    db.commit()
    row = db.execute('SELECT * FROM recipes WHERE id = ?', (cur.lastrowid,)).fetchone()
    return jsonify(recipe_to_dict(db, row)), 201


@app.route('/recipes/<recipeId>', methods=['GET'])
def get_recipe(recipeId):
    db = get_db()
    try:
        rid = int(recipeId)
    except (ValueError, TypeError):
        return Response('Recipe not found', status=404, mimetype='text/plain')
    row = db.execute('SELECT * FROM recipes WHERE id = ?', (rid,)).fetchone()
    if row is None:
        return Response('Recipe not found', status=404, mimetype='text/plain')

    recipe = recipe_to_dict(db, row)
    parts = ['<html><head><title>%s</title></head><body>' % escape_html(recipe['title'])]
    parts.append('<h1>%s</h1>' % escape_html(recipe['title']))
    parts.append('<h2>Ingredients</h2><ul>')
    for ing in recipe['ingredients']:
        parts.append('<li>%s</li>' % escape_html(ing))
    parts.append('</ul>')
    parts.append('<h2>Instructions</h2><p>%s</p>' % escape_html(recipe['instructions']))
    if recipe['avgRating'] is not None:
        parts.append('<h2>Average Rating</h2><p>%.2f / 5</p>' % recipe['avgRating'])
    else:
        parts.append('<h2>Average Rating</h2><p>No ratings yet</p>')
    parts.append('<h2>Comments</h2><ul>')
    for c in recipe['comments']:
        parts.append('<li>%s</li>' % escape_html(c['comment']))
    parts.append('</ul>')
    parts.append('</body></html>')
    return Response(''.join(parts), mimetype='text/html')


@app.route('/recipes/<recipeId>/comments', methods=['POST'])
def add_comment(recipeId):
    db = get_db()
    try:
        rid = int(recipeId)
    except (ValueError, TypeError):
        return jsonify({'error': 'Recipe not found'}), 404
    row = db.execute('SELECT id FROM recipes WHERE id = ?', (rid,)).fetchone()
    if row is None:
        return jsonify({'error': 'Recipe not found'}), 404

    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid input'}), 400
    comment = data.get('comment')
    if not isinstance(comment, str) or not comment.strip():
        return jsonify({'error': 'Invalid input'}), 400

    db.execute('INSERT INTO comments (recipe_id, comment) VALUES (?, ?)', (rid, comment))
    db.commit()
    return jsonify({'message': 'Comment added successfully'}), 201


@app.route('/recipes/<recipeId>/ratings', methods=['POST'])
def add_rating(recipeId):
    db = get_db()
    try:
        rid = int(recipeId)
    except (ValueError, TypeError):
        return jsonify({'error': 'Recipe not found'}), 404
    row = db.execute('SELECT id FROM recipes WHERE id = ?', (rid,)).fetchone()
    if row is None:
        return jsonify({'error': 'Recipe not found'}), 404

    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid input'}), 400
    rating = data.get('rating')
    # Strict validation: must be a real int (not bool), within 1..5 inclusive.
    # Reject floats, strings, booleans, None, and anything outside the range.
    if isinstance(rating, bool) or not isinstance(rating, int):
        return jsonify({'error': 'Invalid input'}), 400
    if rating < 1 or rating > 5:
        return jsonify({'error': 'Invalid input'}), 400

    db.execute('INSERT INTO ratings (recipe_id, rating) VALUES (?, ?)', (rid, rating))
    db.commit()
    return jsonify({'message': 'Rating added successfully'}), 201


